  function formatDeliveryETA(dateStr, carrier) {
    if (!dateStr) return "-";
    try {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return dateStr;
      const opts = { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true };
      const formatted = d.toLocaleString('en-IN', opts);
      return carrier ? `${formatted} (${carrier.replace('Blitz - ', '')})` : formatted;
    } catch (e) {
      return dateStr;
    }
  }

  async function searchCatalog(query) {
    const url = `https://api.croma.com/searchservices/v1/search?query=${encodeURIComponent(query)}:relevance&channelCode=400001&channel=WEB&currentPage=0&fields=FULL`;
    const res = await fetch(url, { headers: API_HEADERS });
    if (!res.ok) throw new Error(`Search error ${res.status}`);
    const data = await res.json();
    return data.products || [];
  }

  async function checkSLA(sku, pincode, fulfillmentType = "SDEL") {
    const payload = {
      promise: {
        allocationRuleID: "SYSTEM",
        checkInventory: "Y",
        organizationCode: "CROMA",
        sourcingClassification: "EC",
        promiseLines: {
          promiseLine: [{
            fulfillmentType: fulfillmentType,
            itemID: String(sku),
            lineId: "1",
            reqEndDate: "2500-01-01",
            reqStartDate: "",
            requiredQty: "1",
            shipToAddress: {
              zipCode: String(pincode),
              extn: { irlAddressLine1: "", irlAddressLine2: "" }
            },
            extn: { widerStoreFlag: "N" }
          }]
        }
      }
    };

    try {
      const res = await fetch("https://api.croma.com/inventory/oms/v2/tms/details-pwa/", {
        method: "POST",
        headers: API_HEADERS,
        body: JSON.stringify(payload)
      });
      if (!res.ok) return null;
      const data = await res.json();
      const lines = data?.promise?.suggestedOption?.option?.promiseLines?.promiseLine;
      if (lines && lines.length > 0) {
        const line = lines[0];
        const assignments = line.assignments?.assignment || [];
        const shipNode = assignments[0]?.shipNode;
        const deliveryDate = assignments[0]?.deliveryDate;
        if (shipNode) {
          return {
            available: true,
            shipNode: shipNode,
            storeName: STORE_NAMES[shipNode] || `Store ${shipNode}`,
            carrier: line.carrierServiceCode || "Standard",
            deliveryDate: deliveryDate || "Available"
          };
        }
      }
    } catch (e) {}
    return null;
  }

